CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, mobile VARCHAR(30), address VARCHAR(500), city VARCHAR(120), state VARCHAR(120), pin_code VARCHAR(20), password_hash VARCHAR(100) NOT NULL, role VARCHAR(40) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_user_role(role));
CREATE TABLE assets (id BIGINT AUTO_INCREMENT PRIMARY KEY, asset_code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, category VARCHAR(50) NOT NULL, location_text VARCHAR(500) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', owner_id BIGINT NOT NULL, assigned_engineer_id BIGINT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_asset_owner FOREIGN KEY(owner_id) REFERENCES users(id), CONSTRAINT fk_asset_engineer FOREIGN KEY(assigned_engineer_id) REFERENCES users(id), INDEX ix_asset_category(category));
CREATE TABLE work_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(30) NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, asset_id BIGINT NULL, reporter_id BIGINT NOT NULL, reviewer_id BIGINT NULL, assignee_id BIGINT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_work_asset FOREIGN KEY(asset_id) REFERENCES assets(id), CONSTRAINT fk_work_reporter FOREIGN KEY(reporter_id) REFERENCES users(id), CONSTRAINT fk_work_reviewer FOREIGN KEY(reviewer_id) REFERENCES users(id), CONSTRAINT fk_work_assignee FOREIGN KEY(assignee_id) REFERENCES users(id), INDEX ix_work_status(status));
CREATE TABLE predictions (id BIGINT AUTO_INCREMENT PRIMARY KEY, asset_id BIGINT NULL, requested_by BIGINT NOT NULL, model_name VARCHAR(100) NOT NULL, model_version VARCHAR(80), status VARCHAR(30) NOT NULL, result_json JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_prediction_asset FOREIGN KEY(asset_id) REFERENCES assets(id), CONSTRAINT fk_prediction_user FOREIGN KEY(requested_by) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, title VARCHAR(180) NOT NULL, message VARCHAR(500) NOT NULL, read_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id), INDEX ix_notice_user_read(user_id,read_at));
